    ),
    ins_sv as (
      insert into public.syllabus_vocabulary (syllabus_id, vocabulary_id, introduced_level)
      select p_syllabus_id, t.vocabulary_id, 1
      from target_300 t
      where exists (select 1 from public.vocabulary v where v.id = t.vocabulary_id)
      on conflict (syllabus_id, vocabulary_id) do nothing
      returning vocabulary_id
    )
    select count(*) into v_syllabus_linked
    from public.syllabus_vocabulary
    where syllabus_id = p_syllabus_id;
  end if;

  select count(*) into v_total_vocab from public.vocabulary;
  select count(*) into v_orphaned_cards
  from public.review_cards rc
  where not exists (select 1 from public.vocabulary v where v.id = rc.vocabulary_id);

  if v_orphaned_cards <> 0 then
    raise exception 'CATALOG_SYNC_ORPHANED_REVIEW_CARDS' using errcode = '23503';
  end if;

  return jsonb_build_object(
    'updated_pilot_count', v_updated_pilot,
    'upserted_new_count', v_upserted_new,
    'syllabus_linked_count', v_syllabus_linked,
    'total_vocabulary_count', v_total_vocab,
    'orphaned_review_cards_count', v_orphaned_cards
  );
end;
$$;

revoke all on function private.sync_hsk1_canonical_vocabulary_catalog(uuid) from public, anon, authenticated;

do $$
begin
  if exists (select 1 from public.syllabus_versions where id = '8b8b06ff-5563-5a67-9197-9ffc9b25a8f9'::uuid) then
    perform private.sync_hsk1_canonical_vocabulary_catalog('8b8b06ff-5563-5a67-9197-9ffc9b25a8f9'::uuid);
  end if;
end;
$$;
